def transform(g):
    from collections import Counter
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # connected components (4-conn) of non-bg
    seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]!=bg:
                            seen[x][y]=True; st.append((x,y))
                comps.append(comp)
    comps.sort(key=len, reverse=True)
    sample=comps[0]; marks=[c[0] for c in comps[1:] if len(c)==1]
    rs=[p[0] for p in sample]; cs=[p[1] for p in sample]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    S=[[g[i][j] for j in range(c0,c1+1)] for i in range(r0,r1+1)]
    ch,cw=r0+(r1-r0)//2-r0, c0+(c1-c0)//2-c0  # center index
    ch=(r1-r0)//2; cw=(c1-c0)//2
    o=[row[:] for row in g]
    for (mr,mc) in marks:
        for si in range(len(S)):
            for sj in range(len(S[0])):
                x,y=mr-ch+si, mc-cw+sj
                if 0<=x<h and 0<=y<w: o[x][y]=S[si][sj]
    return o
